const D = { scale: 1, energy: .68, speed: 1, density: .7, detune: .5, hue: 200, x: .5, y: .5, style: 'spectral', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
if (!S.g || S.gw !== width || S.gh !== height) {
  S.g = createGraphics(width, height); S.g.pixelDensity(1); S.g.colorMode(HSB, 360, 100, 100, 100);
  S.gw = width; S.gh = height;
}
const g = S.g;

if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.pen = [];
  for (let k = 0; k < 3; k++) {
    const b = k * 30;
    const fx1 = 2 + Math.floor(fr(b + 1) * 4);              // 2..5
    const fy1 = 2 + Math.floor(fr(b + 2) * 4);              // 2..5
    const sg = j => (fr(b + 20 + j) < 0.5 ? -1 : 1);
    S.pen.push({
      fx1: fx1, fx2: fx1 + 1 + Math.floor(fr(b + 3) * 3),   // detuned partner
      fy1: fy1, fy2: fy1 + 1 + Math.floor(fr(b + 4) * 3),
      px: [fr(b + 5) * 6.283, fr(b + 6) * 6.283],
      py: [fr(b + 7) * 6.283, fr(b + 8) * 6.283],
      ax: [0.62 + fr(b + 9) * 0.30, 0.34 + fr(b + 10) * 0.30],
      ay: [0.62 + fr(b + 11) * 0.30, 0.34 + fr(b + 12) * 0.30],
      damp: 0.55 + fr(b + 13) * 0.85,                       // 0.55..1.4 (moderate inward spiral, still fills)
      wx: [sg(0) * (0.4 + fr(b + 14) * 0.7), sg(1) * (0.4 + fr(b + 15) * 0.7)],
      wy: [sg(2) * (0.4 + fr(b + 16) * 0.7), sg(3) * (0.4 + fr(b + 17) * 0.7)]
    });
  }
  S.hoff = fr(99) * 30;
}

const style = P.style;
const isAdd = (style === 'spectral' || style === 'gold' || style === 'neon');
let ground;
if (style === 'blueprint') ground = [215, 72, 20];
else if (style === 'ink') ground = [35, 14, 80];
else if (style === 'gold') ground = [32, 62, 7];
else ground = [242, 55, 7];                                 // spectral / neon dark ground

g.push();
g.noFill();
g.blendMode(g.BLEND);
g.background(ground[0], ground[1], ground[2]);
if (isAdd) g.blendMode(g.ADD);

const drift = K.t * (0.12 + P.speed * 0.45);                // continuous incommensurate phase precession = motion floor
const rot = K.t * 0.02 * P.speed;
const cr = Math.cos(rot), sr = Math.sin(rot);
const cx = P.x * width, cy = P.y * height;
const R = u * 0.46 * (0.32 + P.scale * 0.9) * (0.95 + 0.05 * Math.sin(K.t * 0.5));
const TAU = 16 + P.detune * 20;
const steps = Math.floor(300 + P.density * 320);
const intens = 0.6 + K.intensity * 0.6;
const glowE = (0.5 + P.energy * 0.9) * intens * (1 + A.rms * 0.8 + A.bass * 0.5);
const hb = (P.hue + S.hoff + K.section * 18) % 360;

for (let k = 0; k < 3; k++) {
  const pen = S.pen[k];
  const pts = new Float32Array((steps + 1) * 2);
  for (let s = 0; s <= steps; s++) {
    const tau = (s / steps) * TAU;
    const dfac = Math.exp(-pen.damp * tau / TAU);
    const x = R * dfac * (pen.ax[0] * Math.sin(pen.fx1 * tau + pen.px[0] + drift * pen.wx[0]) + pen.ax[1] * Math.sin(pen.fx2 * tau + pen.px[1] + drift * pen.wx[1]));
    const y = R * dfac * (pen.ay[0] * Math.sin(pen.fy1 * tau + pen.py[0] + drift * pen.wy[0]) + pen.ay[1] * Math.sin(pen.fy2 * tau + pen.py[1] + drift * pen.wy[1]));
    pts[s * 2] = cx + (x * cr - y * sr);
    pts[s * 2 + 1] = cy + (x * sr + y * cr);
  }
  const phk = (hb + k * 118) % 360;
  // pass 1 — wide dim glow
  if (isAdd) {
    g.strokeWeight(4.5 + P.energy * 3.2);
    for (let s = 0; s < steps; s++) {
      const f = s / steps; let hh, sat;
      if (style === 'gold') { hh = (36 + f * 26 + k * 7) % 360; sat = 80; }
      else if (style === 'neon') { hh = (phk + f * 62 + drift * 26) % 360; sat = 96; }
      else { hh = (phk + f * 44) % 360; sat = 88; }
      g.stroke(hh, sat, 100, 6.5 + glowE * 7);
      g.line(pts[s * 2], pts[s * 2 + 1], pts[s * 2 + 2], pts[s * 2 + 3]);
    }
  } else if (style === 'blueprint') {
    g.strokeWeight(3.2);
    for (let s = 0; s < steps; s++) { g.stroke(200, 45, 100, 7 + glowE * 4); g.line(pts[s * 2], pts[s * 2 + 1], pts[s * 2 + 2], pts[s * 2 + 3]); }
  } else {
    g.strokeWeight(3.0);
    for (let s = 0; s < steps; s++) { g.stroke(hb, 24, 24, 11); g.line(pts[s * 2], pts[s * 2 + 1], pts[s * 2 + 2], pts[s * 2 + 3]); }
  }
  // pass 2 — bright core
  g.strokeWeight(style === 'ink' ? 1.5 : 1.3);
  for (let s = 0; s < steps; s++) {
    const f = s / steps; let hh, sat, br, al;
    if (style === 'gold') { hh = (44 + f * 16) % 360; sat = 52; br = 100; al = 88; }
    else if (style === 'neon') { hh = (phk + f * 62 + drift * 26) % 360; sat = 72; br = 100; al = 92; }
    else if (style === 'blueprint') { hh = 200; sat = 12; br = 100; al = 90; }
    else if (style === 'ink') { hh = hb; sat = 38; br = 10; al = 90; }
    else { hh = (phk + f * 44) % 360; sat = 48; br = 100; al = 90; }
    g.stroke(hh, sat, br, al);
    g.line(pts[s * 2], pts[s * 2 + 1], pts[s * 2 + 2], pts[s * 2 + 3]);
  }
}
g.blendMode(g.BLEND);
g.pop();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// audio-reactive central bloom (partial, additive, on top of clk baseline — zero during silence)
if (isAdd && (A.treble > 0.02 || A.rms > 0.02)) {
  push(); blendMode(ADD); noStroke();
  drawingContext.shadowBlur = 18 + A.rms * 30; drawingContext.shadowColor = 'rgba(255,255,255,0.7)';
  fill((hb + 30) % 360, 36, 100, (A.treble * 0.5 + A.rms * 0.4) * 40);
  ellipse(cx, cy, u * 0.05);
  drawingContext.shadowBlur = 0; blendMode(BLEND); pop();
}
